// A TypeSpec emitter that writes DXNS (T682, dextrin/design/typespec-emitter.md):
// TypeSpec's compiler resolves the program, and this walks the types the
// user declared and writes them as .dxns files in dextrin's tree layout --
// one file per namespace, following the construct table of
// dextrin/design/typespec.md. Generated files say so in a header and are
// never edited; the same program always gives the same bytes.

import { createTypeSpecLibrary, emitFile, resolvePath, getSourceLocation } from "@typespec/compiler";
import { decode, encode } from "@joetjen/dextrin";
import { typeText, declarationText, namedInstances, namespacePath } from "./types.js";
import { timeline, versionedEntries } from "./versions.js";

/** The library TypeSpec loads. */
export const $lib = createTypeSpecLibrary({
  name: "@joetjen/dextrin-typespec",
  diagnostics: {
    "not-exact": {
      severity: "warning",
      messages: { default: (args) => `${args.what} has no exact DXNS form: ${args.why}` },
    },
  },
});

/**
 * Called by `tsp compile --emit @joetjen/dextrin-typespec`.
 * @param {import("@typespec/compiler").EmitContext} context
 */
export async function $onEmit(context) {
  const program = context.program;
  if (program.compilerOptions.noEmit) return;

  for (const [file, entries, sources] of namespaces(program)) {
    const text = `%{${entries.map(([key, val]) => `${key}: ${val}`).join(" ")}}`;
    const laid = encode(decode(text), { pretty: true });
    const from = sources.map((p) => relativePath(program.projectRoot, p)).join(", ");
    const header = `# Generated by @joetjen/dextrin-typespec from ${from}; do not edit.\n`;
    await emitFile(program, {
      path: resolvePath(context.emitterOutputDir, file),
      content: header + laid + "\n",
    });
  }
}

// A path relative to the project root, with `/` between its parts: no
// machine's own directories in a header, so two machines write the same bytes.
function relativePath(root, path) {
  const rel = path.startsWith(root + "/") ? path.slice(root.length + 1) : path.split("/").pop();
  return rel;
}

// The user's namespaces, each with its entries in name order: what is
// declared in the program's own files, not in a library's.
function namespaces(program) {
  const out = new Map();
  const walk = (ns, path) => {
    for (const [childName, child] of ns.namespaces) {
      if (childName === "TypeSpec" || !own(program, child)) continue;
      walk(child, [...path, childName]);
    }

    const decls = [];
    for (const collection of [ns.scalars, ns.models, ns.enums, ns.unions]) {
      for (const decl of collection.values()) if (own(program, decl)) decls.push(decl);
    }
    if (decls.length === 0 || path.length === 0) return;

    // A versioned namespace (Way B): one file per declaration and DXNS
    // version, in the namespace's directory, `Name.dxns` or `Name-vN.dxns`.
    const versions = timeline(program, ns);
    if (versions) {
      const own = decls.filter((d) => d !== versionEnum(program, ns));
      for (const { name, version, text } of versionedEntries(program, own, versions)) {
        const decl = own.find((d) => d.name === name);
        const file = `${path.join("/")}/${name}${version > 1 ? `-v${version}` : ""}.dxns`;
        out.set(file, [[[name, text]], [getSourceLocation(decl).file.path]]);
      }
      return;
    }

    const entries = [];
    const sources = new Set();
    for (const decl of decls) {
      const text = declarationText(program, decl);
      if (text === undefined) continue;
      entries.push([decl.name, text]);
      sources.add(getSourceLocation(decl).file.path);
    }
    if (entries.length > 0) out.set(`${path.join(".")}.dxns`, [entries, [...sources]]);
  };

  walk(program.getGlobalNamespaceType(), []);

  // Template instances with a @friendlyName, and discriminated models'
  // bases, written beside the declarations of their namespace.
  for (const [path, instances] of namedInstances(program)) {
    const file = `${path}.dxns`;
    if (!out.has(file)) out.set(file, [[], []]);
    for (const [name, text] of instances) out.get(file)[0].push([name, text]);
  }

  for (const [entries, sources] of out.values()) {
    entries.sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
    sources.sort();
  }
  return [...out.entries()]
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
    .map(([name, [entries, sources]]) => [name, entries, sources]);
}

// The enum `@versioned` names: the version timeline, no type of the schema.
function versionEnum(program, ns) {
  const versions = timeline(program, ns);
  return versions?.[0]?.enumMember?.enum;
}

// Declared in the program's own files, not in a library under node_modules.
function own(program, type) {
  const location = getSourceLocation(type, { locateId: true });
  return !!location && !location.file.path.includes("/node_modules/") && !location.isSynthetic;
}

export { typeText };
